window.futvizVista("mapa-tiros","<div class=\"rx-mount\" data-rx=\"tiros\" data-rx-id=\"mapa-tiros\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"mapa-tiros\"]={\"id\":\"mapa-tiros\",\"titulo\":\"Mapa de calor de los tiros\",\"bajada\":\"Cada celda es el % de los tiros que sali\u00f3 de ah\u00ed, no un conteo: oscuro es una parte grande del total.\",\"pregunta\":\"\u00bfDesde d\u00f3nde se tira en las 5 ligas?\",\"tabla\":\"tiros\",\"fuente\":\"Understat\",\"enCurso\":{\"2026-27\":9},\"queMirar\":\"Muestra de d\u00f3nde se tira en las 5 ligas. El mapa mira hacia la porter\u00eda: la l\u00ednea de fondo es el borde de arriba y los rect\u00e1ngulos son las \u00e1reas grande y chica. El color reparte el 100% de los tiros que ves entre celdas de 2\u00d72 m, as\u00ed que una celda oscura es una parte grande del total, no \u00abmuchos tiros\u00bb. Con \u00abVer\u00bb, cada punto es un remate: lleno si fue gol y m\u00e1s grande cuanto m\u00e1s val\u00eda.\"};</script>");